-- SEC-052 option (b): per-user rate-limit windows in a table keyed by user id and rule
-- (DATA_MODEL.md sections 6.18 and 21.9). Additive only: one new empty table, its unique key,
-- one index, one foreign key, two check constraints. No existing row changes.
-- There is no down migration; the manual undo is in DATA_MODEL.md section 17.

-- CreateTable (generated by Prisma)
CREATE TABLE "UserRateLimitWindow" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "rule" TEXT NOT NULL,
    "count" INTEGER NOT NULL,
    "resetAt" TIMESTAMPTZ(3) NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "UserRateLimitWindow_pkey" PRIMARY KEY ("id")
);

-- CreateIndex (generated by Prisma)
CREATE INDEX "UserRateLimitWindow_resetAt_idx" ON "UserRateLimitWindow"("resetAt");

-- CreateIndex (generated by Prisma)
CREATE UNIQUE INDEX "UserRateLimitWindow_userId_rule_key" ON "UserRateLimitWindow"("userId", "rule");

-- AddForeignKey (generated by Prisma)
ALTER TABLE "UserRateLimitWindow" ADD CONSTRAINT "UserRateLimitWindow_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- Hand-written below: Prisma cannot express these (DATA_MODEL.md section 13).

-- A row exists only once a request has been counted in its window.
ALTER TABLE "UserRateLimitWindow" ADD CONSTRAINT "UserRateLimitWindow_count_check" CHECK ("count" >= 1);

-- The per-user rules kept in the database. A rule moved here later is a new migration that
-- drops and re-adds this constraint with the longer list.
ALTER TABLE "UserRateLimitWindow" ADD CONSTRAINT "UserRateLimitWindow_rule_check" CHECK (
  "rule" IN ('seller-application', 'review-create')
);
